let williams = []; // Williamオブジェクトの配列
let unit = 200; // 各セルのサイズ
let columns, rows; // 行数と列数（自動で決定）
let offsetX, offsetY; // 中央配置用オフセット
let pg; // 描画用バッファ

function setup() {
  createCanvas(windowWidth, windowHeight); // 全画面キャンバス作成

  // 画面サイズに収まるだけセルを詰める
  columns = floor(width / unit); // 横に並べられるだけの列数
  rows = floor(height / unit); // 縦に並べられるだけの行数

  // 描画バッファを作成（セルサイズ分だけ）
  pg = createGraphics(columns * unit, rows * unit);

  // 中央に配置するためのオフセットを計算
  offsetX = (width - pg.width) / 2;
  offsetY = (height - pg.height) / 2;

  // Williamオブジェクトを生成して配列に格納
  for (let i = 0; i < columns; i++) {
    for (let j = 0; j < rows; j++) {
      let x = i * unit;
      let y = j * unit;
      williams.push(new William(createVector(x, y), random(TWO_PI)));
    }
  }
}

function draw() {
  // === Variant 4: Dynamic Feedback Trail ===
  // Lower background clear to force deep visual echoing

  pg.fill(0, 15); // バッファの背景を透明で塗りつぶし
  pg.noStroke(); // 線なし
  pg.rect(0, 0, pg.width, pg.height); // バッファを更新

  // 各オブジェクトを更新・描画
  for (let w of williams) {
    w.update(); // 回転などを更新
    w.display(pg); // バッファ上に描画
  }

  background(10, 10, 15, 6); // メインキャンバスの背景を黒に
  image(pg, offsetX, offsetY); // バッファを中央に表示
}

// Williamクラス定義
class William {
  constructor(pos, rotation) {
    this.pos = pos;
    this.rotation = rotation;
    this.rotationSpeed = random(-0.02, 0.02);
    this.p = [];
    this.shift = createVector(random(-unit * 0.2, unit * 0.2), random(-unit * 0.2, unit * 0.2));
    this.res = round(unit * 0.1 * 2);
    this.m = round(unit * 0.1);
    this.radius = unit * 0.25;
    this.angle = 0;
    this.flex = 180;
    this.offset = random(-this.flex, this.flex);
    this.calculatePoints();
  }

  calculatePoints() {
    this.p = [];
    let tmp = createVector(0, 0);
    let dir = createVector(this.m, 0);
    for (let i = 0; i < this.res; i++) {
      this.angle = radians(map(i, 0, this.res, 0, 360) + this.offset);
      let rotatedX = sin(this.angle) * this.radius + this.shift.x;
      let rotatedY = cos(this.angle) * this.radius + this.shift.y;
      let rotated = this.applyRotation(rotatedX, rotatedY, this.rotation);
      this.p[i] = createVector(this.pos.x + unit * 0.5 + rotated.x, this.pos.y + unit * 0.5 + rotated.y);
      this.p[i + this.res] = createVector(this.pos.x + tmp.x, this.pos.y + tmp.y);
      tmp.add(dir);
      if (i + 1 === this.res / 4) dir.set(0, this.m);
      else if (i + 1 === this.res / 2) dir.set(-this.m, 0);
      else if (i + 1 === (this.res * 3) / 4) dir.set(0, -this.m);
    }
  }

  applyRotation(x, y, rotation) {
    let rotatedX = x * cos(rotation) - y * sin(rotation);
    let rotatedY = x * sin(rotation) + y * cos(rotation);
    return createVector(rotatedX, rotatedY);
  }

  update() {
    this.rotation += this.rotationSpeed;
    this.calculatePoints();
  }

  display(g) {
    g.stroke(255, 0, 0, 100);
    for (let i = 0; i < this.res; i++) {
      g.line(this.p[i].x, this.p[i].y, this.p[i + this.res].x, this.p[i + this.res].y);
    }
  }
}

